ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李匡威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李匡威。", "biography": null, "status": "draft", "id": "bdc4b069-347f-5d1c-bafc-bbc5e7e2be44"}, {"name": "王镕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "a3d42aab-7a1f-51f4-84bc-35192b430637"}, {"name": "李抱真（李匡威判官）", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：李抱真（李匡威判官）。", "biography": null, "status": "draft", "id": "52fd287b-4cc3-5cbd-8f84-8512c0656922"}, {"name": "墨君和", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：墨君和。", "biography": null, "status": "draft", "id": "aac78824-9847-54eb-b4f7-67a6f5c57ea0"}, {"name": "李匡筹", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：李匡筹。", "biography": null, "status": "draft", "id": "279717fd-44f2-5b26-a549-6d7701dc5746"}, {"name": "刘仁恭", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“李思安进攻幽州，被刘守光击退”中为卢龙节度使。", "biography": null, "status": "draft", "id": "b8f07571-c891-57ce-b69c-3e4a58148227"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "李神福", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李神福，在此段中为用疑兵解围者。", "biography": null, "status": "draft", "id": "61a41119-a9f8-5beb-8356-77ed00b4ae34"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "田頵", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的田頵，在此段中为击退进攻者。", "biography": null, "status": "draft", "id": "c59b24ec-67c0-5ac6-aaaf-4908d96913b9"}, {"name": "张颢", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“张颢、徐温发动兵谏，控制淮南军政”中为事变组织者。", "biography": null, "status": "draft", "id": "ef6aa295-919e-5b24-8849-186b807fdd8e"}, {"name": "秦宗权", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的秦宗权，在此段中为遣兵者。", "biography": null, "status": "draft", "id": "4ab9b100-f137-522e-9b11-1ef372de9edf"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "status": "draft", "id": "4426793f-0bd8-5a79-919f-7e3a0ddae520"}, {"name": "蔡俦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：蔡俦。", "biography": null, "status": "draft", "id": "259ff539-524f-5563-968a-93bf4928f8e2"}, {"name": "袁稹", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：袁稹。", "biography": null, "status": "draft", "id": "eac76377-40a8-527e-85e8-25317531efb3"}, {"name": "王彦复", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：王彦复。", "biography": null, "status": "draft", "id": "94303240-e248-5f1b-9eec-72479aa3e8cf"}, {"name": "王审知", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加封钱镠、张全义、刘隐等”中为受授者。", "biography": null, "status": "draft", "id": "099c16ed-15be-506b-a65f-aa94c272cbd8"}, {"name": "范晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：范晖。", "biography": null, "status": "draft", "id": "617c88e7-4193-5a9f-b7ac-09b8845d6b96"}, {"name": "董昌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：董昌。", "biography": null, "status": "draft", "id": "873d5b10-b461-5308-baa9-da26022436b4"}, {"name": "陈岩", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：陈岩。", "biography": null, "status": "draft", "id": "a4fc237f-f699-5717-8e95-10a63012cbb8"}, {"name": "王潮", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：王潮。", "biography": null, "status": "draft", "id": "567ec0f2-e484-5547-a92b-847ea79bbaf4"}, {"name": "陈延晦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：陈延晦。", "biography": null, "status": "draft", "id": "b9297e09-06be-5e98-bc25-4d5d1b319899"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "曹诚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：曹诚。", "biography": null, "status": "draft", "id": "cd03fd24-c7a1-5874-8569-46e6abd18763"}, {"name": "李鋋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李鋋。", "biography": null, "status": "draft", "id": "0808f476-1fbf-5463-b686-9f85ba9a30f7"}, {"name": "孙惟晟", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：孙惟晟。", "biography": null, "status": "draft", "id": "700c5541-28bb-5005-86b1-7dbea5c842d4"}, {"name": "陈珮", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：陈珮。", "biography": null, "status": "draft", "id": "ce7e17f1-b477-56f1-bb