ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李匡威助王镕整军，暗谋夺镇", "start_year": 893, "end_year": 893, "time_original": "893年；李匡威在镇州期间，具体月日未载", "dynasty": "唐", "description": "李匡威为王镕修城堑、整甲兵、训士卒，以其年少且自己喜真定风土，暗谋夺取镇州。李抱真从京师回来，为他策划，以私下恩惠笼络将士；镇人爱王氏，不随李匡威。", "phases": [], "location_name": "镇州、真定", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "faf14765-64b0-5b56-ac77-26ee00b5be63"}, {"title": "李匡威伏兵劫王镕，胁同入府", "start_year": 893, "end_year": 893, "time_original": "893年；匡威忌日，具体月日未载", "dynasty": "唐", "description": "李匡威忌日，王镕来吊，匡威素服内穿甲，伏兵劫王镕。王镕抱他劝共回府、以位相让；匡威未接受其说法，但与王镕并马，陈兵入府。大风雷雨中，匡威进东偏门，镇州亲军闭门。", "phases": [], "location_name": "镇州、匡威住宅、军府", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2e1048d9-b48f-56d9-b412-a00b5c54a9e9"}, {"title": "墨君和救王镕，镇人杀李匡威及族党", "start_year": 893, "end_year": 893, "time_original": "劫持入府时；893年，具体日未载", "dynasty": "唐", "description": "屠者墨君和从缺墙跃出，拳击李匡威甲士，将王镕从马上挟救，背上屋顶。镇人取得王镕后进攻并杀李匡威，连同其族党。王镕被挟后颈痛头偏数日。", "phases": [], "location_name": "镇州、东偏门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "69d50c96-0bb2-568d-a36c-4b053adb5caf"}, {"title": "李匡筹奏请讨王镕报兄仇，朝廷不许", "start_year": 893, "end_year": 893, "time_original": "李匡威被杀后；具体日未载", "dynasty": "唐", "description": "李匡筹上奏称王镕杀其兄，请举兵报仇，朝廷不准。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "4d7be956-e1ba-5fcc-9314-39a4c79c3992"}, {"title": "刘仁恭蔚州戍兵思归，奉帅攻幽失利", "start_year": 893, "end_year": 893, "time_original": "893年；李匡筹立后，具体日未载", "dynasty": "唐", "description": "幽州将刘仁恭领兵戍蔚州，超过轮代期，士卒想归乡。李匡筹自立时，戍卒拥刘仁恭为帅，回攻幽州，在居庸关被军府兵击败。", "phases": [], "location_name": "蔚州、幽州、居庸关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5cdee564-3b86-5953-97ff-081cf7fb9194"}, {"title": "刘仁恭奔河东，李克用厚待", "start_year": 893, "end_year": 893, "time_original": "居庸关败后；具体日未载", "dynasty": "唐", "description": "刘仁恭逃奔河东，李克用厚待他。", "phases": [], "location_name": "河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b544af86-2f46-51fe-8d91-e487a076ead1"}, {"title": "李神福围庐州，杨行密田頵会军", "start_year": 893, "end_year": 893, "time_original": "893年四月甲午", "dynasty": "唐", "description": "李神福围庐州，甲午杨行密亲自率军赴庐州，田頵从宣州带兵会合。", "phases": [], "location_name": "庐州、宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f866fa15-46fd-51a3-8a13-89bc9c5f744c"}, {"title": "张颢先事秦孙、孙败归杨后转助蔡俦", "start_year": null, "end_year": null, "time_original": "初及后；具体各阶段年日未载", "dynasty": "唐", "description": "《通鉴》追述蔡人张颢以骁勇事秦宗权，后从孙儒，孙儒败后归杨行密，受厚待被派戍庐州；蔡俦反叛时，张颢又为蔡所用。", "phases": [], "location_name": "庐州、蔡（籍贯）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b3050db8-a215-5a8c-a08e-f33cc4588fc6"}, {"title": "张颢越城降，杨行密拒袁稹请杀改置亲军", "start_year": 893, "end_year": 893, "time_original": "庐州围急时；具体日未载", "dynasty": "唐", "description": "围急，张颢越城来降。杨行密将他隶银枪都使袁稹，袁稹认为他反复，请求杀他；杨行密怕袁稹不能容，便把张颢放到亲军。", "phases": [], "location_name": "庐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b82a3281-f825-559b-9709-c7528d859fc9"}, {"title": "范晖求董昌援，温台婺五千来救", "start_year": 893, "end_year": 893, "time_original": "893年福州久攻期间；具体日未载", "dynasty": "唐", "description": "王彦复、王审知攻福州久不下。范晖向威胜节度使董昌求援，董昌与陈岩有婚姻关系，发温台婺三州兵五千救范晖。", "phases": [], "location_name": "福州、温州、台州、婺州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "82a73b82-cabb-518b-9a8f-1556edef2bd1"}, {"title": "王潮拒福州撤兵，命二将继续攻", "start_year": 893, "end_year": 893, "time_original": "援兵将至、士卒死伤多时", "dynasty": "唐", "description": "王彦复、王审知因城坚、援军将到及伤亡多，向王潮请求撤军改日再攻，王潮拒绝；二将又请王潮亲临，王潮回称兵尽添兵、将尽添将、兵将俱尽才自来。二将惧，亲冒矢石急攻。", "phases": [], "location_name": "福州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "49ce2135-5549-5af6-ac90-f186eaccd7a1"}, {"title": "范晖弃城援军返，王彦复等入福州", "start_year": 893, "end_year": 893, "time_original": "893年五月；庚子入城", "dynasty": "唐", "description": "五月城中粮尽，范晖知不能守，夜把印交监军后弃城逃走，援军也回去；庚子王彦复等进入福州。", "phases": [], "location_name": "福州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "44508bf7-14c4-5662-abb3-d0677c270302"}, {"title": "范晖抵沿海都被将士杀", "start_year": 893, "end_year": 893, "time_original": "893年五月辛丑", "dynasty": "唐", "description": "范晖逃到沿海都，被将士杀死。", "phases": [], "location_name": "沿海都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "198f2968-e67f-537b-8a52-664323699238"}, {"title": "王潮入福州自称留后，葬陈岩、结婚抚其家", "start_year": 893, "end_year": 893, "time_original": "王彦复入福州及范晖死后条；具体日未载", "dynasty": "唐", "description": "王潮进入福州，自称留后，穿素服安葬陈岩，将女儿嫁给陈岩之子陈延晦，厚待陈岩家属。", "phases": [], "location_name": "福州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f409093e-f252-54e0-908d-9d544e15cc67"}, {"title": "汀建归降，岭海二十余盗群降溃", "start_year": 893, "end_year": 893, "time_original": "王潮入福州后条；具体日未载", "dynasty": "唐", "description": "汀州、建州归降，岭海间群盗二十余股均投降或溃散。", "phases": [], "location_name": "汀州、建州、岭海", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7997bf3b-10bc-51cb-b322-3979fa57394c"}, {"title": "钱镠授苏杭观察使", "start_year": 893, "end_year": 893, "time_original": "893年闰月", "dynasty": "唐", "description": "朝廷以武胜防御使钱镠为苏杭观察使。", "phases": [], "location_name": "苏州、杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9a95565a-fb64-5009-85b8-e8bcd0d8074d"}, {"title": "曹诚李鋋孙惟晟被授黔中镇海荆南", "start_year": 893, "end_year": 893, "time_original": "893年闰月", "dynasty": "唐", "description": "朝廷任扈跸都头曹诚为黔中节度使，耀德都头李鋋为镇海节度使，宣威都头孙惟晟为荆南节度使，并同平章事。", "phases": [], "location_name": "黔中、镇海、荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8df97ca6-8cfa-571a-b439-c7518fb5affd"}, {"title": "陈珮被授岭南东道节度使", "start_year": 893, "end_year": 893, "time_original": "893年六月", "dynasty": "唐", "description": "朝廷任捧日都头陈珮为岭南东道节度使，同平章事。", "phases": [], "location_name": "岭南东道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c27b5a65-53f9-549d-8124-8c35bfe899c9"}, {"title": "昭宗为解兵柄，令四都头赴镇", "start_year": 893, "end_year": 893, "time_original": "前述加恩授镇时；893年，具体日未载", "dynasty": "唐", "description": "《通鉴》述李茂贞跋扈，皇帝认为武臣难制，想用诸王代替；给上述四都头加恩，解除兵柄，命其赴镇。", "phases": [], "location_name": "京师及所授各镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bce2ef73-ab54-59eb-830b-d2870dc29039"}, {"title": "李匡筹攻乐寿武强报兄耻", "start_year": 893, "end_year": 893, "time_original": "893年六月条；具体日未载", "dynasty": "唐", "description": "李匡筹出兵攻王镕所属乐寿、武强，报李匡威被杀之耻。", "phases": [], "location_name": "乐寿、武强", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d8f6c6e4-9ac4-5391-b4dc-223599d01492"}, {"title": "王镕救邢州，李克用平山败之进镇", "start_year": 893, "end_year": 893, "time_original": "893年秋七月；壬申进镇", "dynasty": "唐", "description": "王镕派兵救邢州，被李克用在平山击败；壬申李克用进攻镇州。", "phases": [], "location_name": "邢州、平山、镇州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d70dba75-3921-511d-89f0-795a3f366fd2"}, {"title": "王镕请助围邢，李克用许并军任县", "start_year": 893, "end_year": 893, "time_original": "七月壬申进镇之后；具体日未载", "dynasty": "唐", "description": "王镕害怕，请以兵粮二十万助攻邢州，李克用答应。李克用在栾城整军，书载合镕兵三万进驻任县，李存信驻琉璃陂。", "phases": [], "location_name": "栾城、任县、琉璃陂、邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0fbd1665-2dc6-52a4-a121-741d9528a2d3"}, {"title": "杨行密克庐州，斩蔡俦", "start_year": 893, "end_year": 893, "time_original": "893年七月丁亥", "dynasty": "唐", "description": "杨行密攻克庐州，杀蔡俦。", "phases": [], "location_name": "庐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f28cb7f8-3a7e-5b48-936b-28c07d04d91c"}, {"title": "杨行密拒发蔡俦父母墓报复", "start_year": 893, "end_year": 893, "time_original": "庐州克后；具体日未载", "dynasty": "唐", "description": "左右请求挖蔡俦父母墓报复，杨行密说蔡俦正因此得罪，自己何必效仿，拒绝该请求。", "phases": [], "location_name": "庐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "530f20f9-4b95-588c-9dd8-43c5ec46aee1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "姻亲", "description": "《通鉴》称董昌与陈岩婚姻，未具婚配双方，保留对称姻亲关系。", "status": "draft", "id": "93c79955-72a7-5020-8d69-5f0f77dac1f6", "person_a": "873d5b10-b461-5308-baa9-da26022436b4", "person_b": "a4fc237f-f699-5717-8e95-10a63012cbb8"}, {"relation_type": "父亲", "description": "陈延晦为陈岩之子；陈岩是陈延晦的父亲。", "status": "draft", "id": "c58fc1c6-61bd-5531-87d6-5c3142ec9b20", "person_a": "a4fc237f-f699-5717-8e95-10a63012cbb8", "person_b": "b9297e09-06be-5e98-bc25-4d5d1b319899"}, {"relation_type": "岳父", "description": "王潮以女妻陈延晦；王潮是陈延晦的岳父，未补其女姓名。", "status": "draft", "id": "43e0b29c-e23b-533b-ad1b-dc33c995f627", "person_a": "567ec0f2-e484-5547-a92b-847ea79bbaf4", "person_b": "b9297e09-06be-5e98-bc25-4d5d1b319899"}]'::jsonb)
