SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李匡威为王镕修城堑、整甲兵、训士卒，以其年少且自己喜真定风土，暗谋夺取镇州。李抱真从京师回来，为他策划，以私下恩惠笼络将士；镇人爱王氏，不随李匡威。", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p014·原文件第67行", "note": "原文：李匡威在镇州，为王镕完城堑，缮甲兵，训士卒，视之如子，匡威以镕年少，且乐真定土风，潜谋夺之。李抱真自京师还，为之画策，阴以恩施悦其将士。王氏在镇久，镇人爱之，不徇匡威。匡威忌日，镕就第吊之。匡威素服衷甲，伏兵劫之，镕趋抱匡威曰：“镕为晋人所困，几亡矣，赖公以有今日；公欲得四州，此固镕之愿也，不若与公共归府，以位让公，则将土莫之拒矣。”匡威不以为然，与镕骈马，陈兵入府，会大风雷雨，屋瓦皆振。匡威入东偏门，镇之亲军闭之，有屠者墨君和自缺垣跃出，拳殴匡威甲士，挟镕于马上，负之登屋。镇人既得镕，攻匡威，杀之，并其族党。镕时年十七，体疏瘦，为君和所挟，颈痛头偏者累日。李匡筹奏镕杀其兄，请举兵复冤；诏不许。；核对说明：视之如子为态度，不建养子关系；意图与人心描述归于书述，不单列现代心理结论。", "status": "draft", "id": "37db601a-26ec-57f6-a0f3-45a172607c25", "subject_id": "faf14765-64b0-5b56-ac77-26ee00b5be63", "source_id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "893年；李匡威在镇州期间，具体月日未载", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p014·原文件第67行", "note": "原文：李匡威在镇州，为王镕完城堑，缮甲兵，训士卒，视之如子，匡威以镕年少，且乐真定土风，潜谋夺之。李抱真自京师还，为之画策，阴以恩施悦其将士。王氏在镇久，镇人爱之，不徇匡威。匡威忌日，镕就第吊之。匡威素服衷甲，伏兵劫之，镕趋抱匡威曰：“镕为晋人所困，几亡矣，赖公以有今日；公欲得四州，此固镕之愿也，不若与公共归府，以位让公，则将土莫之拒矣。”匡威不以为然，与镕骈马，陈兵入府，会大风雷雨，屋瓦皆振。匡威入东偏门，镇之亲军闭之，有屠者墨君和自缺垣跃出，拳殴匡威甲士，挟镕于马上，负之登屋。镇人既得镕，攻匡威，杀之，并其族党。镕时年十七，体疏瘦，为君和所挟，颈痛头偏者累日。李匡筹奏镕杀其兄，请举兵复冤；诏不许。；核对说明：视之如子为态度，不建养子关系；意图与人心描述归于书述，不单列现代心理结论。", "status": "draft", "id": "8d92bd4b-3fef-52eb-81d9-c08e4bfb4d94", "subject_id": "faf14765-64b0-5b56-ac77-26ee00b5be63", "source_id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李匡威：整军并谋夺者。", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p014·原文件第67行", "note": "原文：李匡威在镇州，为王镕完城堑，缮甲兵，训士卒，视之如子，匡威以镕年少，且乐真定土风，潜谋夺之。李抱真自京师还，为之画策，阴以恩施悦其将士。王氏在镇久，镇人爱之，不徇匡威。匡威忌日，镕就第吊之。匡威素服衷甲，伏兵劫之，镕趋抱匡威曰：“镕为晋人所困，几亡矣，赖公以有今日；公欲得四州，此固镕之愿也，不若与公共归府，以位让公，则将土莫之拒矣。”匡威不以为然，与镕骈马，陈兵入府，会大风雷雨，屋瓦皆振。匡威入东偏门，镇之亲军闭之，有屠者墨君和自缺垣跃出，拳殴匡威甲士，挟镕于马上，负之登屋。镇人既得镕，攻匡威，杀之，并其族党。镕时年十七，体疏瘦，为君和所挟，颈痛头偏者累日。李匡筹奏镕杀其兄，请举兵复冤；诏不许。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "76e19615-0685-5ed7-a2da-942030a377b1", "subject_id": "bdc4b069-347f-5d1c-bafc-bbc5e7e2be44", "source_id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李匡威：整军并谋夺者。", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p014·原文件第67行", "note": "原文：李匡威在镇州，为王镕完城堑，缮甲兵，训士卒，视之如子，匡威以镕年少，且乐真定土风，潜谋夺之。李抱真自京师还，为之画策，阴以恩施悦其将士。王氏在镇久，镇人爱之，不徇匡威。匡威忌日，镕就第吊之。匡威素服衷甲，伏兵劫之，镕趋抱匡威曰：“镕为晋人所困，几亡矣，赖公以有今日；公欲得四州，此固镕之愿也，不若与公共归府，以位让公，则将土莫之拒矣。”匡威不以为然，与镕骈马，陈兵入府，会大风雷雨，屋瓦皆振。匡威入东偏门，镇之亲军闭之，有屠者墨君和自缺垣跃出，拳殴匡威甲士，挟镕于马上，负之登屋。镇人既得镕，攻匡威，杀之，并其族党。镕时年十七，体疏瘦，为君和所挟，颈痛头偏者累日。李匡筹奏镕杀其兄，请举兵复冤；诏不许。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "c5792e94-a909-542f-a7a3-8025b2e43247", "subject_id": "6009eb02-2c67-521b-b2fa-8f273bed5611", "source_id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记王镕：镇主及夺位对象。", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p014·原文件第67行", "note": "原文：李匡威在镇州，为王镕完城堑，缮甲兵，训士卒，视之如子，匡威以镕年少，且乐真定土风，潜谋夺之。李抱真自京师还，为之画策，阴以恩施悦其将士。王氏在镇久，镇人爱之，不徇匡威。匡威忌日，镕就第吊之。匡威素服衷甲，伏兵劫之，镕趋抱匡威曰：“镕为晋人所困，几亡矣，赖公以有今日；公欲得四州，此固镕之愿也，不若与公共归府，以位让公，则将土莫之拒矣。”匡威不以为然，与镕骈马，陈兵入府，会大风雷雨，屋瓦皆振。匡威入东偏门，镇之亲军闭之，有屠者墨君和自缺垣跃出，拳殴匡威甲士，挟镕于马上，负之登屋。镇人既得镕，攻匡威，杀之，并其族党。镕时年十七，体疏瘦，为君和所挟，颈痛头偏者累日。李匡筹奏镕杀其兄，请举兵复冤；诏不许。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "6d200551-4beb-5808-a373-c1d27c985948", "subject_id": "a3d42aab-7a1f-51f4-84bc-35192b430637", "source_id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王镕：镇主及夺位对象。", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p014·原文件第67行", "note": "原文：李匡威在镇州，为王镕完城堑，缮甲兵，训士卒，视之如子，匡威以镕年少，且乐真定土风，潜谋夺之。李抱真自京师还，为之画策，阴以恩施悦其将士。王氏在镇久，镇人爱之，不徇匡威。匡威忌日，镕就第吊之。匡威素服衷甲，伏兵劫之，镕趋抱匡威曰：“镕为晋人所困，几亡矣，赖公以有今日；公欲得四州，此固镕之愿也，不若与公共归府，以位让公，则将土莫之拒矣。”匡威不以为然，与镕骈马，陈兵入府，会大风雷雨，屋瓦皆振。匡威入东偏门，镇之亲军闭之，有屠者墨君和自缺垣跃出，拳殴匡威甲士，挟镕于马上，负之登屋。镇人既得镕，攻匡威，杀之，并其族党。镕